import argparse
import concurrent.futures
import os
import shlex
import sys
from urllib.parse import urlparse
from urllib.request import urlopen
from urllib.error import HTTPError, URLError

def process_url(url, outdir, cmd):
    try:
        with urlopen(url) as response:
            if response.getcode() >= 200 and response.getcode() < 300:
                filename = f"{outdir}/{urlparse(url).netloc.split('.')[-1] or 'root'}.dat"
                with open(filename, 'wb') as f:
                    f.write(response.read())
                return (url, cmd, filename)
            else:
                return (url, "ERROR")
    except (HTTPError, URLError):
        return (url, "ERROR")

def run_command(cmd, filename):
    try:
        result = os.system(shlex.split(cmd) + [filename])
        return (filename, result)
    except Exception:
        return (filename, 1)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--outdir', required=True)
    parser.add_argument('--max-parallel', type=int, default=3)
    parser.add_argument('--cmd', required=True)
    parser.add_argument('urls_file', type=str)
    args = parser.parse_args()

    if not os.path.exists(args.outdir):
        sys.exit(1)

    with open(args.urls_file, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=args.max_parallel) as executor:
        futures = []
        for i, url in enumerate(urls, 1):
            future = executor.submit(process_url, url, args.outdir, args.cmd)
            futures.append((future, url, i))

        for future, url, i in futures:
            try:
                result = future.result()
                if result[1] != "ERROR":
                    cmd_result = executor.submit(run_command, args.cmd, f"{args.outdir}/{i}.dat")
                    cmd_result.add_done_callback(lambda x: results.append((url, x.result()[1])))
                else:
                    results.append((url, "ERROR"))
            except Exception:
                results.append((url, "ERROR"))

    for url, exit_code in results:
        if exit_code == "ERROR":
            print(f"{url} ERROR")
        else:
            print(f"{url} {exit_code}")

if __name__ == "__main__":
    main()
